static void Main(string[] args)
{
    int number;
    int goldenCount = 0;
    Console.WriteLine("Enter numbers one by one :");
    while (goldenCount < 2)
    {
        number = int.Parse(Console.ReadLine());
        int original = number;
        int sum = 0;
        while (number > 0)
        {
            int digit = number % 10;
            sum += digit * digit * digit;
            number /= 10;
        }
        if (sum == original)
        {
            goldenCount++;
            Console.WriteLine(original + " is a golden number! (" + goldenCount + "/2)");
        }
    }
    Console.WriteLine("Program ended.");
}

static void Main(string[] args)
{
    int number;
    int currentCount = 0;
    int maxCount = 0;
    Console.WriteLine("Enter numbers one by one (-1 to stop):");
    number = int.Parse(Console.ReadLine());
    while (number != -1)
    {
        if (number % 2 == 0) // عدد زوجي
        {
            currentCount++;
            if (currentCount > maxCount)
                maxCount = currentCount;
        }
        else
        {
            currentCount = 0; // السلسلة انقطعت
        }
        number = int.Parse(Console.ReadLine());
    }
    Console.WriteLine("The longest consecutive even-number sequence length is: " + maxCount);
}

  static void Main(string[] args)
 {
   int num = 0, a = 0, b = 0, c = 0, count = 0, newNum = 0;
   while (num != -1)
   {
      Console.WriteLine("Enter a three-digit number. :");
      num = int.Parse(Console.ReadLine());
      if (num == -1)
          break;
      a += num % 10;
      b += num / 10 % 10;
      c += num / 100;
      count++;
   }
   newNum = (c / count) * 100 + (b / count) * 10 + (a / count);
   Console.WriteLine("NewNum := " + newNum);
}

